    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.keyEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.keyEvent = async function (e) {
    /* sdd-asis-lifecycle:begin keyEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) == 13 || (typeof e !== 'undefined' && e == 13)) {
        if ($c.util.getKeyCode(event) == 13) {
            if (fnAKCKwdSearchCodeType(($c.util.getComponent('AKCKwd')))) {
                await scwin.fnSearchCorpName();
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnInit = async function () {
    /* sdd-asis-lifecycle:begin fnInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    console.warn('[sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDatesOnlyPeriod(' + "-1" + ')');
    if (($c.util.getComponent('ipt_searchFromDate').getValue() == null ? '' : String($c.util.getComponent('ipt_searchFromDate').getValue())) !== '') {
        $c.util.getComponent('cal_startDate').setValue(($c.util.getComponent("ipt_searchFromDate").getValue() || ''));
        $c.util.getComponent('cal_endDate').setValue(($c.util.getComponent("ipt_searchFromDate").getValue() || ''));
    }
    await scwin.fnSearchInit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchInit = async function () {
    /* sdd-asis-lifecycle:begin fnSearchInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const valMenuIdx = ($c.util.getComponent("dma_fnDownloadReq").get("menuIndex") || '');
    if (valMenuIdx === '2' || valMenuIdx === '3') {
        await scwin.fnOrder("3", "D");
    } else {
        await scwin.fnOrder("4", "D");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnOrder
 * @author Inswave
 * @date 2026. 09. 29
 * @param mode stat
 * @returns
 * @hidden N
*/
scwin.fnOrder = async function (mode, stat) {
    /* sdd-asis-lifecycle:begin fnOrder — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnViewTab
 * @author Inswave
 * @date 2026. 09. 29
 * @param tabDiv
 * @returns
 * @hidden N
*/
scwin.fnViewTab = async function (tabDiv) {
    /* sdd-asis-lifecycle:begin fnViewTab — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $(document).find("li[id=menuType]").each(function(index) {
            if ($(this).hasClass("active")) {
                $(this).removeClass("active");
            }
            if (index === tabDiv) {
                $(this).addClass("active");
            }
    });
    $c.util.getComponent("dma_fnDownloadReq").set("menuIndex", tabDiv + 1);
    await scwin.fnSearchInit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd kisComCd ipt_repIsuSrtCd comNm comAbbrv isurSymbl fssUnqNo
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = function (isurCd, kisComCd, ipt_repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + ipt_repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    $c.util.getComponent('AKCKwd').setValue(comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "A" + ipt_repIsuSrtCd);
    $c.util.getComponent("dma_fnDownloadReq").set("searchCodeType", "char");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpName = async function () {
    /* sdd-asis-lifecycle:begin fnSearchCorpName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
        Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
} else {
    await scwin.fnSearchInit();
}
/* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpNameAllCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param items
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    /* sdd-asis-lifecycle:begin fnSearchCorpNameAllCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (items.length == 1) {
        await scwin.fnSearchCorpCode(items[0].repisusrtcd);
    } else {
        if (items.length > 1) {
            Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
    } else {
        await scwin.fnSearchCorpCode('');
    }
}
/* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_repIsuSrtCd
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpCode = async function (ipt_repIsuSrtCd) {
    /* sdd-asis-lifecycle:begin fnSearchCorpCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (ipt_repIsuSrtCd === "") {
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
        const valSearchCodeType = ($c.util.getComponent("dma_fnDownloadReq").get("searchCodeType") || '');
        if (valSearchCodeType === "number") {
            await $c.win.alert("조회한 종목명이 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        }
    } else {
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", ipt_repIsuSrtCd);
        await scwin.fnSearchInit();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!$c.date.isDate($c.util.getComponent('cal_startDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_endDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_startDate').getValue(), $c.util.getComponent('cal_endDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    if ($c.date.addYear($c.util.getComponent('cal_startDate').getValue(), 3) < $c.date.addYear($c.util.getComponent('cal_endDate').getValue(), 0)) {
        await $c.win.alert("조회기간은 3년 이내만 가능합니다.");
        return;
    }
    const valMenuIdx = ($c.util.getComponent("dma_fnDownloadReq").get("menuIndex") || '');
    const radioArr = $(document).find("input:radio[name=rd_marketType]");
    scwin.hCoumn1.setStyle("display", "");
    scwin.hCoumn2.setStyle("display", "none");
    if (valMenuIdx === '1') {
        $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstcautnisu_sub");
    } else {
        if (valMenuIdx === '2') {
            $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstwarnisu_sub");
        } else {
            if (valMenuIdx === '3') {
                $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstriskisu_sub");
            } else {
                if (valMenuIdx === '4') {
                    $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstcautnisuelw_sub");
                } else {
                    if (valMenuIdx === '5') {
                        scwin.hCoumn1.setStyle("display", "none");
                        scwin.hCoumn2.setStyle("display", "");
                        $c.util.getComponent("dma_fnDownloadReq").set("forward", "invstcautnisuets_sub");
                    } else {
                        return;
                    }
                }
            }
        }
    }
    if (valMenuIdx === '5') {
        radioArr[4].checked = true;
    } else {
        if (valMenuIdx !== '5' && radioArr[4].checked) {
            radioArr[0].checked = true;
        }
    }
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "investattentwarnriskySub");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


